const MissionControlButton = ({ children, onClick, className = "" }: { children: React.ReactNode, onClick?: () => void, className?: string }) => (
   <button
      className={`mission-control-btn-3d px-12 ${className}`}
      onClick={onClick}
   >
      {children}
   </button>
);

const SettingsToggle = ({ checked, onChange, disabled = false }: { checked: boolean, onChange: (v: boolean) => void, disabled?: boolean }) => (
   <button
      onClick={() => !disabled && onChange(!checked)}
      disabled={disabled}
      className={`w-12 h-6 rounded-full transition-all duration-300 relative flex items-center px-0.5 ${disabled ? 'opacity-40 cursor-not-allowed' : checked ? 'bg-gradient-to-r from-blue-500 to-blue-600 shadow-[0_0_10px_rgba(59,130,246,0.3)]' : 'bg-slate-300 dark:bg-slate-700 shadow-inner'}`}
   >
      <div className={`w-5 h-5 bg-white rounded-full transition-all duration-500 shadow-[0_2px_4px_rgba(0,0,0,0.2)] ${checked ? 'translate-x-6' : 'translate-x-0'}`} />
   </button>
);

const RockerSwitch = ({ checked, onChange, disabled = false }: { checked: boolean, onChange: (v: boolean) => void, disabled?: boolean }) => (
   <div
      onClick={() => !disabled && onChange(!checked)}
      className={`relative w-[60px] h-[30px] rounded-lg cursor-pointer transition-all duration-300 ${disabled ? 'opacity-40 grayscale pointer-events-none' : ''}`}
   >
      <div className={`absolute inset-0 rounded-lg border-2 border-slate-200 dark:border-[#333333] dark:border-[#333333] bg-slate-100 dark:bg-[#1A1A1A] dark:bg-[#1A1A1A] shadow-inner`} />
      <motion.div
         animate={{ x: checked ? 30 : 2 }}
         className={`absolute top-1/2 -translate-y-1/2 w-7 h-5 rounded-md shadow-md z-10 ${checked ? 'bg-blue-600 shadow-blue-500/40' : 'bg-slate-400 dark:bg-slate-600'}`}
      />
      <div className="absolute inset-0 flex items-center justify-around text-[8px] font-black uppercase tracking-tighter text-slate-400 select-none px-1">
